public class Node_getChildBefore_TriageGen0Test {



    @Test
    public void testGetChildBefore_MiddleChildReturnsPrevious() {
        Node parent = new Node(1);
        Node child1 = new Node(2);
        Node child2 = new Node(3);
        Node child3 = new Node(4);

        parent.addChildToBack(child1);
        parent.addChildToBack(child2);
        parent.addChildToBack(child3);

        // Testing middle child
        assertEquals("Should return child1 when requesting before child2", child1, parent.getChildBefore(child2));
        // Testing last child
        assertEquals("Should return child2 when requesting before child3", child2, parent.getChildBefore(child3));
    }






}

