public class Node_getChildBefore_TriageGen0Test {





    @Test
    public void testGetChildBefore_NodeNotInParentThrowsException() {
        Node parent = new Node(1);
        Node actualChild = new Node(2);
        Node stranger = new Node(3);

        parent.addChildToBack(actualChild);

        // The method iterates through siblings. If it reaches the end without finding the node, it throws RuntimeException
        try {
            parent.getChildBefore(stranger);
            fail("Should have thrown a RuntimeException because the node is not a child");
        } catch (RuntimeException e) {
            assertEquals("node is not a child", e.getMessage());
        }
    }




}

